#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Exact-blob NIGHTLY vs PR93 BREAK with live-pad reverse crossfades.

The source projections must come from the named Git revisions. The IMA counter
is inserted in a throwaway copy of the identical GPL header for both builds.
Test speeds/lengths are projected only in scratch after original Git-blob checks.
This is producer evidence, not independent QA or microcontroller timing.
"""
import argparse
import hashlib
import json
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile

COMMON = {
    'firmware/src/dsp/ima_adpcm.h': '9ba16e4fe9f0cb643c95a68d540042ab2581d4de',
    'firmware/src/dsp/fastmath.h': '7d2e41bf70590bafa8af0a7376bb912bf763b098',
    'firmware/src/dsp/x0x_param.h': 'f7c9bf22b0606946905790dc20497a2e4b2cb4a6',
    'firmware/src/seq/pattern.h': '9a0703418aae95b14f1b70905cfac916da38d7dd',
}
RENDERERS = {
    'nightly': {
        'firmware/src/dsp/breaks.c': '1d3d692b6788d9d1f13901cd7ab13df506cdb72f',
        'firmware/src/dsp/breaks.h': '094af6650333e844311a8806145a6177a0318225',
    },
    'pr93': {
        'firmware/src/dsp/breaks.c': '9e1e607e2ddc3028383bfb6ebc85fbc7ac6864c5',
        'firmware/src/dsp/breaks.h': '6cb71d336c2c90fdc60a9594c2356f3a4379c264',
    },
}
TEST = 'tests/host/breaks_reverse_fast_advance_test.c'
TEST_BLOB = '5e77b152253422d36ab7218669187d02318d21cb'
ORIGINAL_RATES = 'const int rates[]={16,31,32,33,64,257,4096};'
MUSICAL_RATES = 'const int rates[]={2,4,8,12};'
ORIGINAL_SIZES = 'const uint32_t sizes[]={64,65,255,4097,176400};'
LONG_SIZES = 'const uint32_t sizes[]={705600,1411200,2116800};'
FUNC = 'static inline int32_t ima_decode(const uint8_t *d, uint32_t i, int32_t *pred, int32_t *idx)\n{'


def blob(data):
    return hashlib.sha1(b'blob ' + str(len(data)).encode() + b'\0' + data).hexdigest()


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def invoke(args, log):
    p = subprocess.run(args, capture_output=True, text=True, timeout=150, check=False)
    log.write_text('$ ' + ' '.join(map(str, args)) + '\nexit=' + str(p.returncode) +
                   '\nSTDOUT:\n' + p.stdout + '\nSTDERR:\n' + p.stderr)
    return p.returncode, p.stdout


def rows(log):
    result = {}
    for line in log.splitlines():
        if not line.startswith('n='):
            raise RuntimeError('unexpected runner output: ' + line[:80])
        d = dict(part.split('=', 1) for part in line.split())
        key = (int(d['n']), d['direction'], int(d['rate']), int(d['trial']))
        if key in result or int(d['audible']) < 1 or d['stopped'] != '1':
            raise RuntimeError('duplicate, silent, or unstopped case: ' + str(key))
        result[key] = {k: int(d[k]) for k in ('setup', 'decodes', 'max', 'p95', 'p99', 'audible', 'overlap')}
        result[key]['pcm'] = d['pcm']
        if not 0 <= result[key]['p95'] <= result[key]['p99'] <= result[key]['max']:
            raise RuntimeError('invalid per-block order: ' + str(key))
    if len(result) != 48:
        raise RuntimeError('expected 48 exact workload cases, received ' + str(len(result)))
    for key,row in result.items():
        if key[3] == 0 and row['overlap']:
            raise RuntimeError('Unexpected overlap in steady case: ' + str(key))
        if key[1] == 'R' and key[3] == 1 and not row['overlap']:
            raise RuntimeError('Live-pad stimulus failed to create dual active voices: ' + str(key))
    return result


def change_once(text, old, new):
    if text.count(old) != 1:
        raise RuntimeError('Fixture not at expected source: ' + old[:70])
    return text.replace(old, new)


def live_crossfade_fixture(fixture):
    fixture = change_once(fixture, '#define BLOCKS 8', '#define BLOCKS 80')
    fixture = change_once(fixture, 'uint64_t per_block[BLOCKS],sum=0,max=0,hash=',
                          'uint64_t per_block[BLOCKS],sum=0,max=0,overlap=0,hash=')
    fixture = change_once(fixture, '        uint64_t prior=x0x_host_ima_decode_calls;',
         '        if(trial==1 && reverse && j%4==0) {\n'
         '            if(j) breaks_live(b,(j/4-1)%8,0);\n'
         '            if(j+8<BLOCKS) breaks_live(b,(j/4)%8,1);\n'
         '        }\n'
         '        uint64_t prior=x0x_host_ima_decode_calls;')
    fixture = change_once(fixture, '        uint64_t delta=x0x_host_ima_decode_calls-prior;',
                          '        overlap+=(b->v[0].on && b->v[1].on);\n'
                          '        uint64_t delta=x0x_host_ima_decode_calls-prior;')
    fixture = change_once(fixture, ' audible=%" PRIu64 " stopped=1\\n",',
                          ' audible=%" PRIu64 " overlap=%" PRIu64 " stopped=1\\n",')
    fixture = change_once(fixture, 'hash,audible);', 'hash,audible,overlap);')
    return fixture


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--nightly-root', required=True, type=Path)
    p.add_argument('--pr93-root', required=True, type=Path)
    p.add_argument('--output-dir', required=True, type=Path)
    a = p.parse_args()
    if a.output_dir.exists():
        p.error('refusing to overwrite an existing output directory')
    roots = {'nightly': a.nightly_root.resolve(), 'pr93': a.pr93_root.resolve()}
    pins = {}
    for kind in roots:
        pins[kind] = {}
        for name, expected in {**COMMON, **RENDERERS[kind], **({TEST: TEST_BLOB} if kind == 'pr93' else {})}.items():
            actual = blob((roots[kind] / name).read_bytes())
            if actual != expected:
                raise RuntimeError(f'{kind} invalid Git blob {name}: {actual} != {expected}')
            pins[kind][name] = actual
    a.output_dir.mkdir(parents=True, exist_ok=False)
    found = {}
    with tempfile.TemporaryDirectory(prefix='break-nightly-pr93-') as td:
        tmp = Path(td)
        for kind, root in roots.items():
            work = tmp / kind
            for name in pins[kind]:
                to = work / name
                to.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(root / name, to)
            if kind == 'nightly':
                test_to = work / TEST
                test_to.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(roots['pr93'] / TEST, test_to)
            # Only change the pinned fixture's host rate set in a scratch copy.
            # Both implementations receive the exact same stimulus.
            test_to = work / TEST
            fixture = test_to.read_text()
            if fixture.count(ORIGINAL_RATES) != 1 or fixture.count(ORIGINAL_SIZES) != 1:
                raise RuntimeError('pinned fixture rate syntax mismatch')
            test_to.write_text(live_crossfade_fixture(fixture.replace(ORIGINAL_RATES, MUSICAL_RATES).replace(ORIGINAL_SIZES, LONG_SIZES)))
            header = work / 'firmware/src/dsp/ima_adpcm.h'
            s = header.read_text()
            if s.count(FUNC) != 1 or s.count('#include <stdint.h>') != 1:
                raise RuntimeError('unexpected IMA header instrumentation location')
            s = s.replace('#include <stdint.h>', '#include <stdint.h>\nextern volatile uint64_t x0x_host_ima_decode_calls;')
            header.write_text(s.replace(FUNC, FUNC + '\n    ++x0x_host_ima_decode_calls;'))
            for compiler in ('gcc', 'clang'):
                tag = compiler + '-' + kind
                binary = work / tag
                command = [compiler, '-std=c11', '-O2', '-Wall', '-Wextra', '-Werror',
                           '-pedantic', '-ffp-contract=off', '-I' + str(work),
                           str(work / TEST), str(work / 'firmware/src/dsp/breaks.c'),
                           '-lm', '-o', str(binary)]
                ec, _ = invoke(command, a.output_dir / (tag + '-compile.log'))
                if ec:
                    raise RuntimeError(tag + ' compile exit ' + str(ec))
                trace = a.output_dir / (tag + '.pcm')
                ec, stdout = invoke([str(binary), '--check', '--trace', str(trace)],
                                    a.output_dir / (tag + '-run.log'))
                if ec:
                    raise RuntimeError(tag + ' run exit ' + str(ec))
                ec, _ = invoke([str(binary)], a.output_dir / (tag + '-negative.log'))
                if ec != 2:
                    raise RuntimeError(tag + ' invalid-argument exit ' + str(ec) + ' != 2')
                if trace.stat().st_size != 48 * 80 * 64 * 4:
                    raise RuntimeError(tag + ' unexpected trace size')
                found[tag] = {'cases': rows(stdout), 'pcm_sha256': sha(trace),
                              'trace_bytes': trace.stat().st_size}
                trace.unlink()  # no synthetic PCM distribution
    comparisons = {}
    for compiler in ('gcc', 'clang'):
        old = found[compiler + '-nightly']; new = found[compiler + '-pr93']
        if old['pcm_sha256'] != new['pcm_sha256'] or old['cases'].keys() != new['cases'].keys():
            raise RuntimeError('NIGHTLY vs PR93 whole-trace or scenario mismatch: ' + compiler)
        if any(old['cases'][k]['pcm'] != new['cases'][k]['pcm'] or
               old['cases'][k]['audible'] != new['cases'][k]['audible'] or
               old['cases'][k]['overlap'] != new['cases'][k]['overlap'] for k in old['cases']):
            raise RuntimeError('PCM/control mismatch: ' + compiler)
        stats = {}
        for direction in ('R', 'F'):
            ks = [k for k in old['cases'] if k[1] == direction]
            before = sum(old['cases'][k]['decodes'] for k in ks)
            after = sum(new['cases'][k]['decodes'] for k in ks)
            if any(new['cases'][k]['decodes'] > old['cases'][k]['decodes'] for k in ks):
                raise RuntimeError('unexpected increased decoder work: ' + direction)
            stats[direction] = {'overlap_blocks': sum(old['cases'][k]['overlap'] for k in ks),
                                'cases': len(ks), 'baseline_decodes': before,
                                'candidate_decodes': after,
                                'reduction_percent': round(100 * (before - after) / before, 4),
                                'baseline_max_block': max(old['cases'][k]['max'] for k in ks),
                                'candidate_max_block': max(new['cases'][k]['max'] for k in ks)}
            # Show whether users actually benefit at 1-4x, not just at exotic 257x.
            rate_stats = {}
            for rate in (2, 4, 8, 12):
                matching = [k for k in ks if k[2] == rate]
                bsum = sum(old['cases'][k]['decodes'] for k in matching)
                csum = sum(new['cases'][k]['decodes'] for k in matching)
                rate_stats[str(rate)] = {'baseline_decodes': bsum, 'candidate_decodes': csum,
                                         'reduction_percent': round(100 * (bsum - csum) / bsum, 4)}
            stats[direction]['by_speed'] = rate_stats
            matching = [k for k in ks if k[2] in (2, 4)]
            bsum = sum(old['cases'][k]['decodes'] for k in matching)
            csum = sum(new['cases'][k]['decodes'] for k in matching)
            stats[direction]['rates_2_to_4'] = {'baseline_decodes': bsum, 'candidate_decodes': csum,
                 'reduction_percent': round(100 * (bsum - csum) / bsum, 4)}
        comparisons[compiler] = {'trace_sha256': old['pcm_sha256'], 'stats': stats}
    if comparisons['gcc']['trace_sha256'] != comparisons['clang']['trace_sha256']:
        raise RuntimeError('compiler PCM mismatch')
    report = {'revision': 'performance-pr93-dual-voice-crossfade-20261025-r22',
              'producer_only': True, 'firmware_compiler_inputs_modified': False,
              'baseline_nightly_commit': '54f2ffbc3124f7449a69067dc8215a2d91a2e675',
              'candidate_pr93_commit': '847f3aea5d3cd0b71583b5a9920d35236e441d5d',
              'candidate_firmware_tree': 'ee863f9cba6cbfb4e471d199ae408c7694acbac5',
              'pins': pins, 'scratch_rates': [2, 4, 8, 12], 'scratch_lengths': [705600, 1411200, 2116800], 'results': comparisons,
              'source_kind': 'exact-blob C/H/dependencies and pinned C fixture; scratch-only identical lower-rate stimulus; not full repo root build',
              'known_failure': 'original unmodified PR93 fastmath.h UBSan FAIL; PR28 owns',
              'gates': {'independent_QA': 'NOT_RUN', 'Elite_Pro_target_BUILD_ONLY': 'NOT_RUN',
                        'hardware': 'NOT_RUN', 'publication': 'NOT_RUN'}}
    (a.output_dir / 'result.json').write_text(json.dumps(report, sort_keys=True, indent=2) + '\n')
    print('PASS scoped NIGHTLY vs PR93 musical-rate PCM equivalence')
    print(json.dumps(comparisons, sort_keys=True, indent=2))


if __name__ == '__main__':
    try:
        main()
    except (OSError, RuntimeError, subprocess.TimeoutExpired, ValueError) as ex:
        print('FAIL:', ex, file=sys.stderr)
        sys.exit(1)

#!/usr/bin/env python3
"""Compile production routing and bank logic; cover all eleven drum destinations."""
import os
from pathlib import Path
import re
import subprocess
import tempfile
root = Path(__file__).resolve().parents[2]
source = (Path(os.environ.get('SMC_SOURCE_ROOT', root)) / 'firmware/src/app/smc_mixer.c').read_text()
names = ('smc_same', 'smc_home_target', 'smc_page_target', 'smc_target', 'smc_fader_of', 'smc_knob_target', 'smc_bank', 'smc_notice')
functions = []
for helper in ('smc_drum_mix', 'smc_drum_track'):
    match = re.search(r'^static [^\n]+ '+helper+r'\([^\n]*\)\n\{.*?^\}', source, re.M | re.S)
    if match:
        functions.append(match[0])
for name in names:
    match = re.search(r'^static [^\n]+ '+name+r'\([^\n]*\)\n\{.*?^\}', source, re.M | re.S)
    assert match, name
    functions.append(match[0])
harness = r'''
#include <assert.h>
#include <stdint.h>
#include <string.h>
#include "seq/pattern.h"
enum { R_NONE, R_ENG, R_HDR, R_ACT, R_SPAT, R_SREP, T_909, T_808, T_MIX, T_FX, T_MST,
       MX_LEVEL, MX_PAN, MX_CUT, FX_RV_DECAY, FX_DL_FDBK, MST_RESO, V_GLO, FX_RV_LEVEL, FX_DL_LEVEL, MST_DJF, V_HOME, V_MIX, V_PART, V_SEQ,
       O_NONE, O_LIST, O_ASK, NPARTS=5 };
typedef struct { uint8_t kind,a,b,c; } pref_t;
#define PR(k,a,b,c) ((pref_t){k,a,b,c})
#define NONE PR(R_NONE,0,0,0)
static struct { int help,overlay,list_top,list_n,view,part,sel[2]; } ui;
static struct { pref_t r[1][4]; } pg;
static pref_t list_rows[12];
static int kit=-1, clip, stage;
static struct { pref_t target[8],lock_fader[8],lock_knob[8];
    uint8_t value[8],picked,pending,seen,locked,lock_kit,lock_bank;
    uint32_t lock_song_revision; uint16_t lock_song_len; } smc;
static uint32_t song_structure_revision;
static struct song_fixture { unsigned len; } song_data;
static const struct song_fixture *song(void) { return &song_data; }
static uint8_t smc_scaled(pref_t r) { return r.kind==R_NONE ? 0 : 64; }
static int cur_page(void) { return 0; }
static int drum_mix_page(void) { return ui.view==V_MIX ? kit : -1; }
static int smk_clip_mode_on(void) { return clip; }
#define is_drum() (ui.part < 2)
static pref_t find_ref(int t,int track,const char *name) {
    assert(track>=0 && track<NDRUM && (!strcmp(name,"Level") || !strcmp(name,"Pan")));
    return PR(R_ENG,t,track,!strcmp(name,"Pan"));
}
static void build_pages(void) {
    for(int n=0;n<4;n++) pg.r[0][n]=PR(R_ENG,kit ? T_808 : T_909,ui.sel[kit],n);
}
#define smc_select_drum(k,t) (ui.sel[k]=(t),build_pages())
'''
harness += '\n'.join(functions)
harness += r'''
static void unique(void) {
    for(int i=0;i<8;i++) {
        pref_t f=smc_target(i), k=smc_knob_target(i);
        for(int j=0;j<8;j++) {
            if(f.kind!=R_NONE) {
                if(i!=j) assert(!smc_same(f,smc_target(j)));
            }
            if(k.kind!=R_NONE) assert(!smc_same(k,smc_target(j)));
            if(k.kind!=R_NONE && i!=j) assert(!smc_same(k,smc_knob_target(j)));
        }
    }
}
int main(void) {
    /* Owner: include knobs in all three mixer modes. */
    ui.view=V_HOME; ui.overlay=O_NONE;
    for(int n=0;n<8;n++) assert(!smc_same(smc_knob_target(n),smc_home_target(n)));
    unique();
    ui.view=V_MIX; ui.overlay=O_NONE;
    for(int n=0;n<8;n++) assert(!smc_same(smc_knob_target(n),smc_home_target(n)));
    for(kit=0;kit<2;kit++) {
        unsigned seen=0;
        for(int bank=0;bank<2;bank++) {
            assert(smc_bank(bank ? 0x2F : 0x2E));
            smc.picked=255; smc.pending=0;
            for(int n=0;n<8;n++) smc_notice(n);
            assert(smc.picked==0 && smc.pending==255);
            for(int n=0;n<8;n++) {
                pref_t r=smc_target(n);
                if(bank && n>=3) { assert(r.kind==R_NONE); continue; }
                assert(r.kind==R_ENG && r.a==(kit ? T_808:T_909) && r.b==bank*8+n && r.c==0);
                seen |= 1u<<r.b;
            }
            for(int n=0;n<8;n++) { pref_t k=smc_knob_target(n); assert(bank && n>=3 ? k.kind==R_NONE : k.c==1 && k.b==bank*8+n); }
            unique();
        }
        assert(seen==0x7FF);
        ui.sel[kit]=10; build_pages(); assert(smc_target(2).b==10); unique();
        ui.sel[kit]=7; build_pages(); assert(smc_target(7).b==7); unique();
    }
    ui.view=V_PART; kit=-1;
    pg.r[0][0]=PR(R_ENG,T_MIX,0,MX_LEVEL);
    assert(smc_target(0).kind==R_ENG && smc_knob_target(0).kind==R_NONE);
    pg.r[0][1]=pg.r[0][0]; assert(smc_knob_target(1).kind==R_NONE);
    pg.r[0][1]=PR(R_ENG,T_MIX,0,1);
    unique(); assert(!smc_bank(0x2F));
    ui.overlay=O_LIST; ui.list_n=8; ui.list_top=2;
    for(int n=0;n<12;n++) list_rows[n]=PR(R_ENG,T_MIX,n,1);
    for(int n=0;n<8;n++) {
        assert(smc_same(smc_target(n),smc_home_target(n)));
        assert(n<6 ? smc_knob_target(n).b==n+2 : smc_knob_target(n).kind==R_NONE);
    }
    unique();
    ui.help=1;
    for(int n=0;n<8;n++) assert(smc_same(smc_target(n),smc_home_target(n)));
    ui.overlay=O_ASK;
    for(int n=0;n<8;n++) assert(smc_target(n).kind==R_NONE && smc_knob_target(n).kind==R_NONE);
    ui.help=0; ui.overlay=O_NONE; clip=1; stage=1;
    for(int n=0;n<8;n++) assert(smc_same(smc_target(n),smc_home_target(n)));
    return 0;
}
'''
with tempfile.TemporaryDirectory() as tmp:
    c=Path(tmp)/'test.c'; exe=Path(tmp)/'test'; c.write_text(harness)
    subprocess.run([os.environ.get('CC','cc'),'-std=c99','-Wall','-Wextra','-Werror','-I'+str(root/'firmware/src'),str(c),'-o',str(exe)],check=True)
    subprocess.run([str(exe)],check=True)
print('PASS: both drum kits, 11 tracks, bank bounds, three knob modes, unique targets across faders and knobs, menus and stage isolation')

// SPDX-License-Identifier: MPL-2.0
/* Copyright (C) 2026 M. Geisler (genkigenki/makkuro)
 *
 * Settings store calls from the libraries. Stage 2 keeps no store: every read misses and every
 * write fails, so the controller does its full RF trim at each power-on (RFIinitUseTrimValue 0).
 * The RF calibration comes from the boot parameters, which the app fills. */
#include "ctl_port.h"

int syscfg_read(u16 id, void *buf, u16 len) { (void)id; (void)buf; (void)len; return -1; }
int syscfg_write(u16 id, void *buf, u16 len) { (void)id; (void)buf; (void)len; return -1; }

void wifi_get_xosc(u8 *xosc) { memcpy(xosc, ctl_bp->xosc, 2); }
void wifi_get_mcs_dgain(u8 *g) { memcpy(g, ctl_bp->mcs_dgain, sizeof(ctl_bp->mcs_dgain)); }
int wifi_get_pa_trim_data(u8 *pa)
{
    memcpy(pa, ctl_bp->pa_trim, sizeof(ctl_bp->pa_trim));
    return 1;   /* as the SDK default: no automatic tune */
}
int wifi_get_rf_trim_data(void *info, int size) { (void)info; (void)size; return -1; }
int wifi_set_rf_trim_data(void *info, int size) { (void)info; (void)size; return -1; }

/* RF switches read by wl_rf_common (values chosen for this image). */
const u8 RTDebugLevel = 0;
const char WIFI_PA_ENABLE = 0;
const char wifi_temperature_drift_trim_on = 0;  /* off: no ADC in this image */
const u8 RFIinitUseTrimValue = 0;               /* full RF init at each power-on */

// SPDX-License-Identifier: GPL-3.0-only
import test from 'node:test';
import assert from 'node:assert/strict';
import { planMigration, migrationReordersLoopMenu, guardMigrationLoopMenu, installKeepingSlots,
  userSlotRaw, readArchive, pack78 } from './x0x_breaks.js';
const lay = ns => ({count:ns.length, slots:ns.map(nz=>({nz}))});
const om=[{off:0x1000,size:50000},{off:0x20000,size:120000},{off:0x40000,size:50000}];
const nm=[om[0],{off:0x50000,size:80000}];
const images=[new Uint8Array(40000),new Uint8Array(100000),new Uint8Array(30000)];
test('skipped middle multizone image cannot donate its saved LOOP indices to C',()=>{
 const old=lay([1,2,1]), next=lay([1,0]);
 const p=planMigration(images,[1,2],om,next,nm);
 assert.deepEqual(p.todo,[{k:2,j:1}]);assert.equal(p.skipped.length,1);
 const guarded=guardMigrationLoopMenu(old,images,[1,2],om,next,nm,p.todo,p.skipped);
 assert.deepEqual(guarded.todo,[]);assert.equal(guarded.skipped.length,2);
 assert.match(guarded.skipped[1],/compatible layout.*every saved pattern/);
});
test('identical image CRCs do not hide original-slot reorder',()=>{
 const same=[new Uint8Array(800),new Uint8Array(800)], map=om.slice(0,2);
 assert.equal(migrationReordersLoopMenu(lay([2,1]),same,[0,1],map,lay([0,0]),map,[{k:0,j:1},{k:1,j:0}]),true);
 assert.equal(migrationReordersLoopMenu(lay([2,1]),same,[0,1],map,lay([0,0]),map,[{k:0,j:0},{k:1,j:1}]),false);
});
test('safe prefix, trailing omission and append-only occupants retain existing indices',()=>{
